  1→/**
  2→ * Executor Resolution Logic
  3→ *
  4→ * Handles the cascade resolution for hot-swappable executors:
  5→ * Agent Config → Collection Config → System Default
  6→ */
  7→
  8→import { executePackage } from '@tpmjs/package-executor';
  9→import type {
 10→  CreateSessionResponse,
 11→  DestroySessionResponse,
 12→  ExecuteToolRequest,
 13→  ExecuteToolResponse,
 14→  ExecutorConfig,
 15→  ExecutorHealthResponse,
 16→  SandboxExecutorConfig,
 17→} from '@tpmjs/types/executor';
 18→
 19→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
 20→const MAX_RETRIES = 2;
 21→const RETRY_BASE_DELAY_MS = 1000;
 22→
 23→/**
 24→ * Retry helper with exponential backoff
 25→ */
 26→async function withRetry<T>(
 27→  fn: () => Promise<T>,
 28→  opts: { maxRetries?: number; shouldRetry?: (error: unknown) => boolean } = {}
 29→): Promise<T> {
 30→  const maxRetries = opts.maxRetries ?? MAX_RETRIES;
 31→  let lastError: unknown;
 32→
 33→  for (let attempt = 0; attempt <= maxRetries; attempt++) {
 34→    try {
 35→      return await fn();
 36→    } catch (error) {
 37→      lastError = error;
 38→      if (attempt >= maxRetries) break;
 39→      if (opts.shouldRetry && !opts.shouldRetry(error)) break;
 40→
 41→      const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
 42→      console.warn(
 43→        `[Executor] Retry ${attempt + 1}/${maxRetries} after ${delay}ms:`,
 44→        error instanceof Error ? error.message : String(error)
 45→      );
 46→      await new Promise((resolve) => setTimeout(resolve, delay));
 47→    }
 48→  }
 49→
 50→  throw lastError;
 51→}
 52→
 53→/**
 54→ * Resolve executor configuration using cascade:
 55→ * Agent Config → Collection Config → System Default
 56→ *
 57→ * @param agentConfig - Executor config from Agent (highest priority)
 58→ * @param collectionConfig - Executor config from Collection (medium priority)
 59→ * @returns Resolved executor configuration
 60→ */
 61→export function resolveExecutorConfig(
 62→  agentConfig: ExecutorConfig | null | undefined,
 63→  collectionConfig: ExecutorConfig | null | undefined
 64→): ExecutorConfig {
 65→  // Agent config takes precedence
 66→  if (agentConfig && agentConfig.type !== 'default') {
 67→    return agentConfig;
 68→  }
 69→
 70→  // Fall back to collection config
 71→  if (collectionConfig && collectionConfig.type !== 'default') {
 72→    return collectionConfig;
 73→  }
 74→
 75→  // System default
 76→  return { type: 'default' };
 77→}
 78→
 79→/**
 80→ * Parse executor config from database JSON
 81→ * Handles null/undefined and validates the shape
 82→ */
 83→export function parseExecutorConfig(
 84→  executorType: string | null | undefined,
 85→  executorConfig: unknown
 86→): ExecutorConfig | null {
 87→  if (!executorType) {
 88→    return null;
 89→  }
 90→
 91→  if (executorType === 'default') {
 92→    return { type: 'default' };
 93→  }
 94→
 95→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
 96→    const config = executorConfig as { url?: string; apiKey?: string };
 97→    if (config.url && typeof config.url === 'string') {
 98→      return {
 99→        type: 'custom_url',
100→        url: config.url,
101→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
102→      };
103→    }
104→  }
105→
106→  if (executorType === 'sandbox') {
107→    const config =
108→      executorConfig && typeof executorConfig === 'object'
109→        ? (executorConfig as { url?: string; apiKey?: string })
110→        : {};
111→    return {
112→      type: 'sandbox',
113→      url: typeof config.url === 'string' ? config.url : undefined,
114→      apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
115→    };
116→  }
117→
118→  return null;
119→}
120→
121→/**
122→ * Execute a tool using a custom URL executor
123→ */
124→async function executeWithCustomUrl(
125→  url: string,
126→  apiKey: string | undefined,
127→  request: ExecuteToolRequest,
128→  timeout: number = DEFAULT_TIMEOUT
129→): Promise<ExecuteToolResponse> {
130→  const startTime = Date.now();
131→
132→  const headers: Record<string, string> = {
133→    'Content-Type': 'application/json',
134→  };
135→
136→  if (apiKey) {
137→    headers.Authorization = `Bearer ${apiKey}`;
138→  }
139→
140→  try {
141→    const controller = new AbortController();
142→    const timeoutId = setTimeout(() => controller.abort(), timeout);
143→
144→    const response = await fetch(`${url}/execute-tool`, {
145→      method: 'POST',
146→      headers,
147→      body: JSON.stringify(request),
148→      signal: controller.signal,
149→    });
150→
151→    clearTimeout(timeoutId);
152→
153→    const executionTimeMs = Date.now() - startTime;
154→
155→    if (!response.ok) {
156→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
157→        error?: string;
158→      };
159→      return {
160→        success: false,
161→        error: errorData.error || `Executor error: ${response.status}`,
162→        executionTimeMs,
163→      };
164→    }
165→
166→    const result = (await response.json()) as ExecuteToolResponse;
167→
168→    return {
169→      success: result.success,
170→      output: result.output,
171→      error: result.error,
172→      executionTimeMs: result.executionTimeMs || executionTimeMs,
173→    };
174→  } catch (error) {
175→    const executionTimeMs = Date.now() - startTime;
176→
177→    if (error instanceof Error && error.name === 'AbortError') {
178→      return {
179→        success: false,
180→        error: 'Execution timeout',
181→        executionTimeMs,
182→      };
183→    }
184→
185→    return {
186→      success: false,
187→      error: error instanceof Error ? error.message : String(error),
188→      executionTimeMs,
189→    };
190→  }
191→}
192→
193→// =============================================================================
194→// Sandbox Session Management
195→// =============================================================================
196→
197→/**
198→ * Resolve sandbox URL from config or environment variable
199→ */
200→export function resolveSandboxUrl(config: SandboxExecutorConfig): string | null {
201→  return config.url || process.env.AGENT_SANDBOX_URL || null;
202→}
203→
204→/**
205→ * Create or resume a sandbox session (idempotent)
206→ * If the session already exists, extends its TTL and returns it.
207→ */
208→export async function createSandboxSession(
209→  url: string,
210→  apiKey: string | undefined,
211→  sessionId: string,
212→  timeoutSeconds?: number
213→): Promise<CreateSessionResponse> {
214→  return withRetry(
215→    async () => {
216→      const headers: Record<string, string> = { 'Content-Type': 'application/json' };
217→      if (apiKey) {
218→        headers.Authorization = `Bearer ${apiKey}`;
219→      }
220→
221→      const controller = new AbortController();
222→      const timeoutId = setTimeout(() => controller.abort(), 15000);
223→
224→      try {
225→        const response = await fetch(`${url}/sessions`, {
226→          method: 'POST',
227→          headers,
228→          body: JSON.stringify({ sessionId, timeoutSeconds }),
229→          signal: controller.signal,
230→        });
231→
232→        clearTimeout(timeoutId);
233→
234→        if (response.status === 429) {
235→          throw new Error('Sandbox at capacity (429). Retrying...');
236→        }
237→
238→        if (!response.ok) {
239→          const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
240→            error?: string;
241→          };
242→          throw new Error(
243→            errorData.error || `Failed to create sandbox session: ${response.status}`
244→          );
245→        }
246→
247→        return (await response.json()) as CreateSessionResponse;
248→      } catch (error) {
249→        clearTimeout(timeoutId);
250→        if (error instanceof Error && error.name === 'AbortError') {
251→          throw new Error('Sandbox session creation timed out');
252→        }
253→        throw error;
254→      }
255→    },
256→    {
257→      shouldRetry: (error) => {
258→        const msg = error instanceof Error ? error.message : String(error);
259→        // Retry on network errors, timeouts, and capacity issues
260→        return (
261→          msg.includes('timed out') ||
262→          msg.includes('429') ||
263→          msg.includes('ECONNREFUSED') ||
264→          msg.includes('fetch failed')
265→        );
266→      },
267→    }
268→  );
269→}
270→
271→/**
272→ * Destroy a sandbox session (fire-and-forget safe)
273→ * Returns gracefully even if the session doesn't exist.
274→ */
275→export async function destroySandboxSession(
276→  url: string,
277→  apiKey: string | undefined,
278→  sessionId: string
279→): Promise<DestroySessionResponse> {
280→  const headers: Record<string, string> = {};
281→  if (apiKey) {
282→    headers.Authorization = `Bearer ${apiKey}`;
283→  }
284→
285→  try {
286→    const controller = new AbortController();
287→    const timeoutId = setTimeout(() => controller.abort(), 10000);
288→
289→    const response = await fetch(`${url}/sessions/${encodeURIComponent(sessionId)}`, {
290→      method: 'DELETE',
291→      headers,
292→      signal: controller.signal,
293→    });
294→
295→    clearTimeout(timeoutId);
296→
297→    if (!response.ok && response.status !== 404) {
298→      return { sessionId, destroyed: false };
299→    }
300→
301→    return (await response
302→      .json()
303→      .catch(() => ({ sessionId, destroyed: true }))) as DestroySessionResponse;
304→  } catch {
305→    // Fire-and-forget: don't throw on cleanup failures
306→    return { sessionId, destroyed: false };
307→  }
308→}
309→
310→/**
311→ * Execute a tool using a sandbox executor (includes sessionId in request)
312→ */
313→async function executeWithSandbox(
314→  url: string,
315→  apiKey: string | undefined,
316→  request: ExecuteToolRequest,
317→  sessionId: string,
318→  timeout: number = DEFAULT_TIMEOUT
319→): Promise<ExecuteToolResponse> {
320→  const startTime = Date.now();
321→
322→  const headers: Record<string, string> = {
323→    'Content-Type': 'application/json',
324→  };
325→
326→  if (apiKey) {
327→    headers.Authorization = `Bearer ${apiKey}`;
328→  }
329→
330→  // Retry on transient failures (network errors, 429, 502, 503)
331→  let lastError: unknown;
332→  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
333→    try {
334→      const controller = new AbortController();
335→      const timeoutId = setTimeout(() => controller.abort(), timeout);
336→
337→      const response = await fetch(`${url}/execute-tool`, {
338→        method: 'POST',
339→        headers,
340→        body: JSON.stringify({ ...request, sessionId }),
341→        signal: controller.signal,
342→      });
343→
344→      clearTimeout(timeoutId);
345→
346→      const executionTimeMs = Date.now() - startTime;
347→
348→      // Retry on 429 (capacity) or 502/503 (transient server issues)
349→      if (
350→        (response.status === 429 || response.status === 502 || response.status === 503) &&
351→        attempt < MAX_RETRIES
352→      ) {
353→        const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
354→        console.warn(
355→          `[Sandbox] Got ${response.status}, retrying in ${delay}ms (attempt ${attempt + 1})`
356→        );
357→        await new Promise((resolve) => setTimeout(resolve, delay));
358→        continue;
359→      }
360→
361→      if (!response.ok) {
362→        const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
363→          error?: string;
364→        };
365→        return {
366→          success: false,
367→          error: errorData.error || `Sandbox executor error: ${response.status}`,
368→          executionTimeMs,
369→        };
370→      }
371→
372→      const result = (await response.json()) as ExecuteToolResponse;
373→
374→      return {
375→        success: result.success,
376→        output: result.output,
377→        error: result.error,
378→        executionTimeMs: result.executionTimeMs || executionTimeMs,
379→      };
380→    } catch (error) {
381→      lastError = error;
382→
383→      if (error instanceof Error && error.name === 'AbortError') {
384→        return {
385→          success: false,
386→          error: 'Execution timeout',
387→          executionTimeMs: Date.now() - startTime,
388→        };
389→      }
390→
391→      // Retry on network errors
392→      if (attempt < MAX_RETRIES) {
393→        const msg = error instanceof Error ? error.message : String(error);
394→        if (
395→          msg.includes('ECONNREFUSED') ||
396→          msg.includes('fetch failed') ||
397→          msg.includes('ECONNRESET')
398→        ) {
399→          const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
400→          console.warn(
401→            `[Sandbox] Network error, retrying in ${delay}ms (attempt ${attempt + 1}):`,
402→            msg
403→          );
404→          await new Promise((resolve) => setTimeout(resolve, delay));
405→          continue;
406→        }
407→      }
408→
409→      return {
410→        success: false,
411→        error: error instanceof Error ? error.message : String(error),
412→        executionTimeMs: Date.now() - startTime,
413→      };
414→    }
415→  }
416→
417→  return {
418→    success: false,
419→    error: lastError instanceof Error ? lastError.message : String(lastError),
420→    executionTimeMs: Date.now() - startTime,
421→  };
422→}
423→
424→/**
425→ * Execute a tool using the resolved executor configuration
426→ *
427→ * @param config - Resolved executor config (or null for default)
428→ * @param request - Tool execution request
429→ * @param sessionId - Optional session ID for sandbox executors
430→ * @returns Execution result
431→ */
432→export async function executeWithExecutor(
433→  config: ExecutorConfig | null,
434→  request: ExecuteToolRequest,
435→  sessionId?: string
436→): Promise<ExecuteToolResponse> {
437→  const resolvedConfig = config ?? { type: 'default' };
438→
439→  // Use custom URL executor
440→  if (resolvedConfig.type === 'custom_url' && resolvedConfig.url) {
441→    return executeWithCustomUrl(resolvedConfig.url, resolvedConfig.apiKey, request);
442→  }
443→
444→  // Use sandbox executor
445→  if (resolvedConfig.type === 'sandbox' && sessionId) {
446→    const sandboxUrl = resolveSandboxUrl(resolvedConfig);
447→    if (!sandboxUrl) {
448→      return {
449→        success: false,
450→        error:
451→          'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom URL.',
452→        executionTimeMs: 0,
453→      };
454→    }
455→    return executeWithSandbox(sandboxUrl, resolvedConfig.apiKey, request, sessionId);
456→  }
457→
458→  // Default: use existing package-executor (which uses SANDBOX_EXECUTOR_URL)
459→  const result = await executePackage(request.packageName, request.name, request.params, {
460→    env: request.env,
461→    version: request.version,
462→  });
463→
464→  return {
465→    success: result.success,
466→    output: result.output,
467→    error: result.error,
468→    executionTimeMs: result.executionTimeMs,
469→  };
470→}
