529→/**
530→ * Test a custom executor by running a simple tool execution
531→ *
532→ * @param url - Executor URL to test
533→ * @param apiKey - Optional API key for authentication
534→ * @returns Test execution result
535→ */
536→export async function testExecutor(
537→  url: string,
538→  apiKey?: string
539→): Promise<{ success: boolean; executionTimeMs: number; error?: string }> {
540→  const testRequest: ExecuteToolRequest = {
541→    packageName: '@tpmjs/hello',
542→    name: 'helloWorldTool',
543→    version: '0.0.2',
544→    params: { includeTimestamp: true },
545→  };
546→
547→  const result = await executeWithCustomUrl(url, apiKey, testRequest, 30000); // 30 second timeout for test (includes npm install)
548→
549→  return {
550→    success: result.success,
551→    executionTimeMs: result.executionTimeMs,
552→    error: result.error,
553→  };
554→}
