 24→/**
 25→ * Generate a URL-friendly UID from a name
 26→ */
 27→function slugify(name: string): string {
 28→  return name
 29→    .toLowerCase()
 30→    .trim()
 31→    .replace(/[^\w\s-]/g, '')
 32→    .replace(/\s+/g, '-')
 33→    .replace(/-+/g, '-')
 34→    .replace(/^-+|-+$/g, '')
 35→    .slice(0, 50);
 36→}
 37→
 38→/**
 39→ * Generate a unique UID for an agent (globally unique)
 40→ */
 41→async function generateUniqueUid(baseName: string): Promise<string> {
 42→  let uid = slugify(baseName);
 43→  if (!uid) uid = 'agent';
 44→
 45→  // Check if uid exists globally
 46→  const existing = await prisma.agent.findUnique({
 47→    where: { uid },
 48→    select: { id: true },
 49→  });
 50→
 51→  if (!existing) return uid;
 52→
 53→  // Append numbers until unique
 54→  let counter = 1;
 55→  while (counter < 1000) {
 56→    const candidate = `${uid.slice(0, 46)}-${counter}`;
 57→    const exists = await prisma.agent.findUnique({
 58→      where: { uid: candidate },
 59→      select: { id: true },
 60→    });
 61→    if (!exists) return candidate;
 62→    counter++;
 63→  }
 64→
 65→  // Fallback: use random suffix
 66→  return `${uid.slice(0, 42)}-${Date.now().toString(36)}`;
 67→}
