 69→/**
 70→ * POST /api/agents/[id]/clone
 71→ * Clone a public agent to the current user's account
 72→ */
 73→export async function POST(request: NextRequest, context: RouteContext) {
 74→  const requestId = crypto.randomUUID();
 75→
 76→  try {
 77→    const session = await auth.api.getSession({ headers: await headers() });
 78→    if (!session?.user?.id) {
 79→      return apiUnauthorized('Authentication required', requestId);
 80→    }
 81→
 82→    const { id } = await context.params;
 83→
 84→    // Get the source agent
 85→    const sourceAgent = await prisma.agent.findUnique({
 86→      where: { id },
 87→      include: {
 88→        tools: {
 89→          select: { toolId: true, position: true },
 90→        },
 91→        collections: {
 92→          select: { collectionId: true, position: true },
 93→        },
 94→      },
 95→    });
 96→
 97→    if (!sourceAgent) {
 98→      return apiNotFound('Agent', requestId);
 99→    }
100→
101→    // Only public agents can be cloned
102→    if (!sourceAgent.isPublic) {
103→      return apiForbidden('Only public agents can be cloned', requestId);
104→    }
105→
106→    // Don't allow cloning your own agent
107→    if (sourceAgent.userId === session.user.id) {
108→      return apiValidationError('Cannot clone your own agent', undefined, requestId);
109→    }
110→
111→    // Check agent limit
112→    const existingCount = await prisma.agent.count({
113→      where: { userId: session.user.id },
114→    });
115→
116→    if (existingCount >= AGENT_LIMITS.MAX_AGENTS_PER_USER) {
117→      return apiValidationError(
118→        `Maximum ${AGENT_LIMITS.MAX_AGENTS_PER_USER} agents allowed`,
119→        undefined,
120→        requestId
121→      );
122→    }
123→
124→    // Parse optional body for custom name/uid
125→    let customName: string | undefined;
126→    let customUid: string | undefined;
127→
128→    try {
129→      const body = await request.json();
130→      const parsed = CloneAgentSchema.safeParse(body);
131→      if (parsed.success) {
132→        customName = parsed.data.name;
133→        customUid = parsed.data.uid;
134→      }
135→    } catch {
136→      // No body or invalid JSON - use defaults
137→    }
138→
139→    // Generate name and uid
140→    const name = customName || `${sourceAgent.name} (copy)`;
141→    const uid = customUid || (await generateUniqueUid(name));
142→
143→    // Verify uid uniqueness
144→    if (customUid) {
145→      const existingUid = await prisma.agent.findUnique({
146→        where: { uid: customUid },
147→        select: { id: true },
148→      });
149→      if (existingUid) {
150→        return apiValidationError('UID is already taken', { uid: customUid }, requestId);
151→      }
152→    }
153→
154→    // Create the forked agent with all its relationships
155→    // NOTE: envVars and executorConfig are NOT copied - user must add their own
156→    const forkedAgent = await prisma.$transaction(async (tx) => {
157→      // Create the agent with fork reference
158→      const newAgent = await tx.agent.create({
159→        data: {
160→          userId: session.user.id,
161→          uid,
162→          name,
163→          description: sourceAgent.description,
164→          provider: sourceAgent.provider,
165→          modelId: sourceAgent.modelId,
166→          systemPrompt: sourceAgent.systemPrompt,
167→          temperature: sourceAgent.temperature,
168→          maxToolCallsPerTurn: sourceAgent.maxToolCallsPerTurn,
169→          maxMessagesInContext: sourceAgent.maxMessagesInContext,
170→          isPublic: false, // Forked agents start as private
171→          likeCount: 1, // Start with 1 like (from owner)
172→          forkedFromId: sourceAgent.id, // Track fork origin
173→          // NOTE: envVars is intentionally NOT copied - user adds their own API keys
174→          // NOTE: executorConfig is intentionally NOT copied - user configures their own
175→        },
176→      });
177→
178→      // Increment fork count on source agent
179→      await tx.agent.update({
180→        where: { id: sourceAgent.id },
181→        data: { forkCount: { increment: 1 } },
182→      });
183→
184→      // Auto-like the agent
185→      await tx.agentLike.create({
186→        data: {
187→          userId: session.user.id,
188→          agentId: newAgent.id,
189→        },
190→      });
191→
192→      // Clone tool relationships
193→      if (sourceAgent.tools.length > 0) {
194→        await tx.agentTool.createMany({
195→          data: sourceAgent.tools.map((at) => ({
196→            agentId: newAgent.id,
197→            toolId: at.toolId,
198→            position: at.position,
199→          })),
200→        });
201→      }
202→
203→      // Clone collection relationships (only user's own collections)
204→      const userCollectionIds = await tx.collection.findMany({
205→        where: {
206→          userId: session.user.id,
207→          id: { in: sourceAgent.collections.map((ac) => ac.collectionId) },
208→        },
209→        select: { id: true },
210→      });
211→
212→      if (userCollectionIds.length > 0) {
213→        const validCollectionIds = new Set(userCollectionIds.map((c) => c.id));
214→        await tx.agentCollection.createMany({
215→          data: sourceAgent.collections
216→            .filter((ac) => validCollectionIds.has(ac.collectionId))
217→            .map((ac) => ({
218→              agentId: newAgent.id,
219→              collectionId: ac.collectionId,
220→              position: ac.position,
221→            })),
222→        });
223→      }
224→
225→      return newAgent;
226→    });
227→
228→    // Log activity as FORK
229→    logActivity({
230→      userId: session.user.id,
231→      type: 'AGENT_FORKED',
232→      targetName: forkedAgent.name,
233→      targetType: 'agent',
234→      agentId: forkedAgent.id,
235→      metadata: {
236→        sourceAgentId: sourceAgent.id,
237→        sourceAgentName: sourceAgent.name,
238→      },
239→    });
240→
241→    return apiSuccess(
242→      {
243→        id: forkedAgent.id,
244→        uid: forkedAgent.uid,
245→        name: forkedAgent.name,
246→        description: forkedAgent.description,
247→        isPublic: forkedAgent.isPublic,
248→        forkedFromId: forkedAgent.forkedFromId,
249→        createdAt: forkedAgent.createdAt,
250→      },
251→      { requestId, status: 201 }
252→    );
253→  } catch (error) {
254→    console.error('[API Error] POST /api/agents/[id]/clone:', error);
255→    return apiInternalError('Failed to clone agent', requestId);
256→  }
257→}
