666→/**
667→ * GET /api/[username]/agents/[agentSlug]/conversation/[conversationId]
668→ * Retrieve conversation history with pagination
669→ */
670→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
671→  const { username, agentSlug, conversationId } = await context.params;
672→  const { searchParams } = new URL(request.url);
673→
674→  const format = searchParams.get('format');
675→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
676→  const before = searchParams.get('before');
677→  const after = searchParams.get('after');
678→
679→  try {
680→    // Fetch agent by username and slug
681→    const agent = await prisma.agent.findFirst({
682→      where: {
683→        uid: agentSlug,
684→        user: { username },
685→      },
686→      select: {
687→        id: true,
688→        uid: true,
689→        name: true,
690→        provider: true,
691→        modelId: true,
692→        executorType: true,
693→        executorConfig: true,
694→      },
695→    });
696→
697→    if (!agent) {
698→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
699→    }
700→
701→    // Fetch conversation
702→    const conversation = await prisma.conversation.findUnique({
703→      where: {
704→        agentId_slug: {
705→          agentId: agent.id,
706→          slug: conversationId,
707→        },
708→      },
709→    });
710→
711→    if (!conversation) {
712→      return NextResponse.json(
713→        { success: false, error: 'Conversation not found' },
714→        { status: 404 }
715→      );
716→    }
717→
718→    // For JSON format, return all messages with full details
719→    if (format === 'json') {
720→      const allMessages = await prisma.message.findMany({
721→        where: { conversationId: conversation.id },
722→        orderBy: { createdAt: 'asc' },
723→      });
724→
725→      const response = {
726→        _meta: {
727→          exportedAt: new Date().toISOString(),
728→          format: 'tpmjs-conversation-log',
729→          version: '1.0',
730→        },
731→        agent: {
732→          id: agent.id,
733→          uid: agent.uid,
734→          name: agent.name,
735→          provider: agent.provider,
736→          modelId: agent.modelId,
737→          executorType: agent.executorType,
738→          executorConfig: agent.executorConfig,
739→        },
740→        conversation: {
741→          id: conversation.id,
742→          slug: conversation.slug,
743→          title: conversation.title,
744→          createdAt: conversation.createdAt,
745→          updatedAt: conversation.updatedAt,
746→          messageCount: allMessages.length,
747→        },
748→        messages: allMessages.map((m) => ({
749→          id: m.id,
750→          role: m.role,
751→          content: m.content,
752→          toolCalls: m.toolCalls,
753→          toolCallId: m.toolCallId,
754→          toolName: m.toolName,
755→          toolResult: m.toolResult,
756→          inputTokens: m.inputTokens,
757→          outputTokens: m.outputTokens,
758→          createdAt: m.createdAt,
759→        })),
760→        stats: {
761→          totalMessages: allMessages.length,
762→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
763→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
764→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
765→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
766→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
767→        },
768→      };
769→
770→      // Return pretty-printed JSON with proper content type
771→      return new NextResponse(JSON.stringify(response, null, 2), {
772→        headers: {
773→          'Content-Type': 'application/json',
774→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
775→        },
776→      });
777→    }
778→
779→    // Standard paginated response
780→    const whereClause: {
781→      conversationId: string;
782→      createdAt?: { lt?: Date; gt?: Date };
783→    } = { conversationId: conversation.id };
784→
785→    if (before) {
786→      whereClause.createdAt = { lt: new Date(before) };
787→    } else if (after) {
788→      whereClause.createdAt = { gt: new Date(after) };
789→    }
790→
791→    // Determine fetch order:
792→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
793→    // - "after": Fetch asc (oldest first) to get messages after the cursor
794→    const shouldFetchDesc = !after;
795→
796→    // Fetch messages
797→    const messages = await prisma.message.findMany({
798→      where: whereClause,
799→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
800→      take: limit + 1,
801→    });
802→
803→    const hasMore = messages.length > limit;
804→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
805→
806→    // Reverse if we fetched in desc order to maintain chronological order
807→    if (shouldFetchDesc) {
808→      paginatedMessages = paginatedMessages.reverse();
809→    }
810→
811→    const mappedMessages = paginatedMessages.map((m) => ({
812→      id: m.id,
813→      role: m.role,
814→      content: m.content,
815→      toolCalls: m.toolCalls,
816→      toolCallId: m.toolCallId,
817→      toolName: m.toolName,
818→      toolResult: m.toolResult,
819→      inputTokens: m.inputTokens,
820→      outputTokens: m.outputTokens,
821→      createdAt: m.createdAt,
822→    }));
823→
824→    return NextResponse.json({
825→      success: true,
826→      data: {
827→        id: conversation.id,
828→        slug: conversation.slug,
829→        title: conversation.title,
830→        createdAt: conversation.createdAt,
831→        updatedAt: conversation.updatedAt,
832→        messages: mappedMessages,
833→      },
834→      pagination: {
835→        limit,
836→        hasMore,
837→        ...(before && { before }),
838→        ...(after && { after }),
839→      },
840→    });
841→  } catch (error) {
842→    console.error('Failed to fetch conversation:', error);
843→    return NextResponse.json(
844→      { success: false, error: 'Failed to fetch conversation' },
845→      { status: 500 }
846→    );
847→  }
848→}
849→
850→/**
851→ * DELETE /api/[username]/agents/[agentSlug]/conversation/[conversationId]
852→ * Delete a conversation
853→ */
854→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
855→  const { username, agentSlug, conversationId } = await context.params;
856→
857→  try {
858→    // Fetch agent by username and slug (include executor fields for sandbox cleanup)
859→    const agent = await prisma.agent.findFirst({
860→      where: {
861→        uid: agentSlug,
862→        user: { username },
863→      },
864→      select: { id: true, executorType: true, executorConfig: true },
865→    });
866→
867→    if (!agent) {
868→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
869→    }
870→
871→    // Destroy sandbox session if applicable (fire-and-forget)
872→    if (agent.executorType === 'sandbox') {
873→      const { parseExecutorConfig, resolveSandboxUrl, destroySandboxSession } = await import(
874→        '@/lib/executors'
875→      );
876→      const sandboxConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
877→      if (sandboxConfig && sandboxConfig.type === 'sandbox') {
878→        const sandboxUrl = resolveSandboxUrl(sandboxConfig);
879→        if (sandboxUrl) {
880→          const sessionId = `${agent.id}:${conversationId}`;
881→          destroySandboxSession(sandboxUrl, sandboxConfig.apiKey, sessionId).catch(() => {});
882→        }
883→      }
884→    }
885→
886→    // Delete conversation (messages cascade)
887→    await prisma.conversation.deleteMany({
888→      where: {
889→        agentId: agent.id,
890→        slug: conversationId,
891→      },
892→    });
893→
894→    return NextResponse.json({
895→      success: true,
896→      data: { deleted: true },
897→    });
898→  } catch (error) {
899→    console.error('Failed to delete conversation:', error);
900→    return NextResponse.json(
901→      { success: false, error: 'Failed to delete conversation' },
902→      { status: 500 }
903→    );
904→  }
905→}
