1114→  }
1115→
1116→  if (error || !agent) {
1117→    return (
1118→      <DashboardLayout title="Error" showBackButton backUrl="/dashboard/agents">
1119→        <div className="text-center py-16">
1120→          <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
1121→          <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
1122→          <p className="text-foreground-secondary mb-4">{error || 'Agent not found'}</p>
1123→          <Link href="/dashboard/agents">
1124→            <Button>Back to Agents</Button>
1125→          </Link>
1126→        </div>
1127→      </DashboardLayout>
1128→    );
1129→  }
1130→
1131→  const envVarsCount = envVars ? Object.keys(envVars).length : 0;
1132→
1133→  const pageTabs = [
1134→    { id: 'tools' as const, label: 'Tools', count: agentTools.length },
1135→    { id: 'collections' as const, label: 'Collections', count: agentCollections.length },
