1142→    { id: 'settings' as const, label: 'Settings' },
1143→  ];
1144→
1145→  return (
1146→    <DashboardLayout
1147→      title={agent.name}
1148→      subtitle={`${PROVIDER_DISPLAY_NAMES[agent.provider]} / ${agent.modelId}`}
1149→      showBackButton
1150→      backUrl="/dashboard/agents"
1151→      actions={
