1153→          <Button>
1154→            <Icon icon="message" size="sm" className="mr-2" />
1155→            Chat
1156→          </Button>
1157→        </Link>
1158→      }
1159→    >
1160→      {/* Status badges */}
1161→      <div className="flex items-center gap-2 mb-6">
1162→        <Badge variant={agent.isPublic ? 'success' : 'secondary'}>
1163→          {agent.isPublic ? 'Public' : 'Private'}
1164→        </Badge>
1165→        {executorConfig?.type === 'custom_url' && (
1166→          <Badge variant="secondary">Custom Executor</Badge>
1167→        )}
1168→        {executorConfig?.type === 'sandbox' && <Badge variant="secondary">Agent Sandbox</Badge>}
1169→      </div>
1170→
1171→      {/* Tabs */}
1172→      <Tabs tabs={pageTabs} activeTab={activeTab} onTabChange={handleTabChange} className="mb-6" />
1173→
1174→      {/* Tools Tab */}
1175→      {activeTab === 'tools' && (
1176→        <div className="bg-surface border border-border rounded-lg overflow-hidden">
1177→          {/* Add Tool Search */}
1178→          <div ref={toolSearchRef} className="relative p-4 border-b border-border">
1179→            <div className="relative">
1180→              <Icon
1181→                icon="search"
1182→                size="xs"
1183→                className="absolute left-3 top-1/2 -translate-y-1/2 text-foreground-tertiary"
1184→              />
1185→              <input
1186→                type="text"
1187→                value={toolSearch}
1188→                onChange={(e) => {
1189→                  setToolSearch(e.target.value);
1190→                  setShowToolSearch(true);
1191→                }}
1192→                onFocus={() => setShowToolSearch(true)}
1193→                placeholder="Search tools to add..."
1194→                className="w-full pl-9 pr-3 py-2 bg-surface border border-border rounded-lg text-foreground text-sm placeholder:text-foreground-tertiary focus:outline-none focus:ring-2 focus:ring-primary/50 focus:border-primary"
1195→              />
1196→              {isSearchingTools && (
1197→                <div className="absolute right-3 top-1/2 -translate-y-1/2">
1198→                  <Spinner size="sm" />
1199→                </div>
1200→              )}
1201→            </div>
1202→
1203→            {/* Search Results Dropdown */}
1204→            {showToolSearch && toolSearch && (
1205→              <div className="absolute z-10 left-4 right-4 mt-1 bg-surface border border-border rounded-lg shadow-lg max-h-64 overflow-y-auto">
1206→                {toolSearchResults.length > 0 ? (
