1490→                </div>
1491→                <div>
1492→                  <Label htmlFor="modelId">Model</Label>
1493→                  <Select
1494→                    id="modelId"
1495→                    name="modelId"
1496→                    value={formData.modelId}
1497→                    onChange={handleChange}
1498→                    options={models.map((m) => ({ value: m.id, label: m.name }))}
