1500→                </div>
1501→              </div>
1502→
1503→              <div>
1504→                <Label htmlFor="systemPrompt">System Prompt</Label>
1505→                <Textarea
1506→                  id="systemPrompt"
1507→                  name="systemPrompt"
1508→                  value={formData.systemPrompt}
1509→                  onChange={handleChange}
1510→                  rows={6}
1511→                  resize="none"
1512→                />
1513→              </div>
1514→
1515→              <div className="grid gap-4 sm:grid-cols-3">
1516→                <div>
1517→                  <Label htmlFor="temperature">Temperature</Label>
1518→                  <Input
1519→                    type="number"
1520→                    id="temperature"
1521→                    name="temperature"
1522→                    value={formData.temperature}
1523→                    onChange={handleChange}
1524→                    min={0}
1525→                    max={2}
