1536→                    onChange={handleChange}
1537→                    min={1}
1538→                    max={100}
1539→                  />
1540→                </div>
1541→                <div>
1542→                  <Label htmlFor="maxMessagesInContext">Context Messages</Label>
1543→                  <Input
1544→                    type="number"
1545→                    id="maxMessagesInContext"
1546→                    name="maxMessagesInContext"
1547→                    value={formData.maxMessagesInContext}
1548→                    onChange={handleChange}
1549→                    min={1}
1550→                    max={100}
1551→                  />
1552→                </div>
1553→              </div>
1554→
1555→              <div className="flex items-center justify-between p-4 bg-surface-secondary rounded-lg border border-border">
1556→                <div>
1557→                  <p className="text-sm font-medium text-foreground">Public Visibility</p>
1558→                  <p className="text-xs text-foreground-secondary">
1559→                    Make this agent visible on the public agents page
1560→                  </p>
1561→                </div>
1562→                <Switch
1563→                  checked={formData.isPublic}
1564→                  onChange={(checked) => setFormData((prev) => ({ ...prev, isPublic: checked }))}
1565→                />
1566→              </div>
1567→
1568→              <div className="flex justify-end pt-2">
1569→                <Button onClick={handleSave} disabled={isSaving}>
