 77→/**
 78→ * POST /api/agents/[id]/conversation/[conversationId]
 79→ * Send a message and stream the AI response via SSE
 80→ */
 81→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
 82→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 83→  const startTime = Date.now();
 84→
 85→  // Authenticate request (supports both session and API key)
 86→  const authResult = await authenticateRequest();
 87→
 88→  if (!authResult.authenticated) {
 89→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 90→  }
 91→
 92→  // Check scope for API key auth
 93→  if (authResult.authenticated && !authResult.isSessionAuth) {
 94→    if (!hasScope(authResult, 'agent:chat')) {
 95→      return NextResponse.json(
 96→        { error: 'API key does not have agent:chat scope' },
 97→        { status: 403 }
 98→      );
 99→    }
100→  }
101→
102→  // Check rate limit (after auth so we can track by user if needed)
103→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
104→  if (rateLimitResponse) {
105→    return rateLimitResponse;
106→  }
107→
108→  const { id: agentId, conversationId } = await context.params;
109→
110→  try {
111→    const body = await request.json();
112→    const parsed = SendMessageSchema.safeParse(body);
113→    if (!parsed.success) {
114→      return NextResponse.json(
115→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
116→        { status: 400 }
117→      );
118→    }
119→
120→    // Fetch agent with all tool relations using agent ID
121→    const { fetchAgentWithTools, buildAgentTools } = await import('@/lib/agents/build-tools');
122→    const { getRequiredEnvVarsForAgent, getMissingEnvVars } = await import(
123→      '@/lib/agents/env-helpers'
124→    );
125→    const agent = await fetchAgentWithTools(agentId);
126→
127→    if (!agent) {
128→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
129→    }
130→
131→    // Check ownership
132→    const isOwner = authResult.userId === agent.userId;
133→
134→    // Non-owners can only access PUBLIC agents
135→    if (!isOwner && !agent.isPublic) {
136→      // Don't reveal that the agent exists - return 404
137→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
138→    }
139→
140→    // Map provider to expected key name format
141→    const providerKeyNames: Record<string, string> = {
142→      OPENAI: 'OPENAI_API_KEY',
143→      ANTHROPIC: 'ANTHROPIC_API_KEY',
144→      GOOGLE: 'GOOGLE_API_KEY',
145→      GROQ: 'GROQ_API_KEY',
146→      MISTRAL: 'MISTRAL_API_KEY',
147→    };
148→    const keyName = providerKeyNames[agent.provider];
149→
150→    if (!keyName) {
151→      return NextResponse.json(
152→        { success: false, error: `Unsupported provider: ${agent.provider}` },
153→        { status: 400 }
154→      );
155→    }
156→
157→    let apiKey: string;
158→    let callerEnvVars: Record<string, string> | undefined;
159→
160→    if (isOwner) {
161→      // Owner: use stored encrypted keys
162→      const userApiKey = await prisma.userApiKey.findUnique({
163→        where: {
164→          userId_keyName: {
165→            userId: agent.userId,
166→            keyName,
167→          },
168→        },
169→      });
170→
171→      if (!userApiKey) {
172→        return NextResponse.json(
173→          {
174→            success: false,
175→            error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
176→          },
177→          { status: 400 }
178→        );
179→      }
180→
181→      // Decrypt the API key
182→      apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
183→      // callerEnvVars stays undefined - buildAgentTools will use agent's stored env vars
184→    } else {
185→      // Non-owner accessing public agent: must provide their own credentials
186→      if (!parsed.data.providerApiKey) {
187→        return NextResponse.json(
188→          {
189→            success: false,
190→            error: 'Public agent access requires your own API key',
191→            details: {
192→              code: 'MISSING_PROVIDER_KEY',
193→              requiredProvider: agent.provider,
194→              hint: `Provide your ${agent.provider} API key in the 'providerApiKey' field`,
195→            },
196→          },
197→          { status: 400 }
198→        );
199→      }
200→
201→      apiKey = parsed.data.providerApiKey;
202→      callerEnvVars = parsed.data.env || {};
203→
204→      // Check for required environment variables
205→      const requiredEnvVars = getRequiredEnvVarsForAgent(agent);
206→      const missingEnvVars = getMissingEnvVars(requiredEnvVars, callerEnvVars);
207→
208→      if (missingEnvVars.length > 0) {
209→        return NextResponse.json(
210→          {
211→            success: false,
212→            error: 'Missing required environment variables',
213→            details: {
214→              code: 'MISSING_ENV_VARS',
215→              missingVars: missingEnvVars.map((e) => ({
216→                name: e.name,
217→                description: e.description,
218→              })),
219→              hint: "Provide these variables in the 'env' field of your request",
220→            },
221→          },
222→          { status: 400 }
223→        );
224→      }
225→    }
226→
227→    // Get or create conversation
228→    let conversation = await prisma.conversation.findUnique({
229→      where: {
230→        agentId_slug: {
231→          agentId: agent.id,
232→          slug: conversationId,
233→        },
234→      },
235→    });
236→
237→    if (!conversation) {
238→      conversation = await prisma.conversation.create({
239→        data: {
240→          agentId: agent.id,
241→          slug: conversationId,
242→          title: parsed.data.message.slice(0, 100),
243→        },
244→      });
245→
246→      // Log activity for new conversation (fire-and-forget)
247→      if (agent.userId) {
248→        logActivity({
249→          userId: agent.userId,
250→          type: 'AGENT_CONVERSATION_STARTED',
251→          targetName: agent.name,
252→          targetType: 'agent',
253→          agentId: agent.id,
254→        });
255→      }
256→    }
257→
258→    // Fetch recent messages for context
259→    const recentMessages = await prisma.message.findMany({
260→      where: { conversationId: conversation.id },
261→      orderBy: { createdAt: 'desc' },
262→      take: agent.maxMessagesInContext,
263→    });
264→
265→    // Reverse to get chronological order
266→    recentMessages.reverse();
267→
268→    // Save user message
269→    await prisma.message.create({
270→      data: {
271→        conversationId: conversation.id,
272→        role: 'USER',
273→        content: parsed.data.message,
274→      },
275→    });
276→
277→    // Build AI SDK messages from conversation history
278→    const { streamText, stepCountIs } = await import('ai');
279→
280→    const messages: ModelMessage[] = [];
281→
282→    // Add system prompt if defined
283→    if (agent.systemPrompt) {
284→      messages.push({
285→        role: 'system',
286→        content: agent.systemPrompt,
287→      });
288→    }
289→
290→    // Build a set of tool call IDs that have corresponding tool results
291→    // This is needed because AI SDK requires every tool call to have a matching tool result
292→    const toolResultIds = new Set(
293→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
294→    );
295→
296→    // Add conversation history - properly format for AI SDK
297→    for (const msg of recentMessages) {
298→      if (msg.role === 'USER') {
299→        messages.push({ role: 'user', content: msg.content });
300→      } else if (msg.role === 'ASSISTANT') {
301→        // For assistant messages with tool calls, include ToolCallParts in content
302→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
303→          // Only include tool calls that have matching tool results
304→          // AI SDK fails if there's a tool call without a corresponding tool result
305→          const validToolCalls = (
306→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
307→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
308→
309→          if (validToolCalls.length > 0) {
310→            const toolCallParts = validToolCalls.map((tc) => ({
311→              type: 'tool-call' as const,
312→              toolCallId: tc.toolCallId,
313→              toolName: tc.toolName,
314→              input: tc.args,
315→            }));
316→            // Content includes text (if any) plus tool call parts
317→            const content: Array<
318→              | { type: 'text'; text: string }
319→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
320→            > = [];
321→            if (msg.content) {
322→              content.push({ type: 'text', text: msg.content });
323→            }
324→            content.push(...toolCallParts);
325→            messages.push({
326→              role: 'assistant',
327→              content,
328→            });
329→          } else {
330→            // All tool calls are missing results, just include text content
331→            messages.push({
332→              role: 'assistant',
333→              content: msg.content || '',
334→            });
335→          }
336→        } else {
337→          messages.push({
338→            role: 'assistant',
339→            content: msg.content,
340→          });
341→        }
342→      } else if (msg.role === 'TOOL') {
343→        // Tool results use the 'tool' role with content array
344→        messages.push({
345→          role: 'tool',
346→          content: [
347→            {
348→              type: 'tool-result' as const,
349→              toolCallId: msg.toolCallId || '',
350→              toolName: msg.toolName || '',
351→              output: {
352→                type: 'json' as const,
353→                value: msg.toolResult,
354→              },
355→            },
356→          ],
357→        });
358→      }
359→    }
360→
361→    // Add new user message
362→    messages.push({ role: 'user', content: parsed.data.message });
363→
364→    // Set up sandbox session if agent uses sandbox executor
365→    let sessionId: string | undefined;
366→    if (agent.executorType === 'sandbox') {
367→      const { parseExecutorConfig, resolveSandboxUrl, createSandboxSession } = await import(
368→        '@/lib/executors'
369→      );
370→      const sandboxConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
371→      if (sandboxConfig && sandboxConfig.type === 'sandbox') {
372→        const sandboxUrl = resolveSandboxUrl(sandboxConfig);
373→        if (!sandboxUrl) {
374→          return NextResponse.json(
375→            {
376→              success: false,
377→              error:
378→                'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom sandbox URL.',
379→            },
380→            { status: 502 }
381→          );
382→        }
383→        sessionId = `${agent.id}:${conversationId}`;
384→        try {
385→          await createSandboxSession(sandboxUrl, sandboxConfig.apiKey, sessionId);
386→        } catch (error) {
387→          console.error('[Sandbox] Failed to create session:', error);
388→          return NextResponse.json(
389→            {
390→              success: false,
391→              error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
392→            },
393→            { status: 502 }
394→          );
395→        }
396→      }
397→    }
398→
399→    // Build tools from agent configuration
400→    // Build tools - pass callerEnvVars if non-owner accessing public agent
401→    const tools = buildAgentTools(agent, callerEnvVars, sessionId);
402→
403→    // Get the provider model
404→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
405→
406→    // Create SSE stream
407→    const stream = new ReadableStream({
408→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
409→      async start(controller) {
410→        const encoder = new TextEncoder();
411→
412→        const sendEvent = (event: string, data: unknown) => {
413→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
414→          controller.enqueue(encoder.encode(message));
415→        };
416→
417→        try {
418→          const startTime = Date.now();
419→          let fullContent = '';
420→          // Accumulate tool calls with their input args
421→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
422→            new Map();
423→          // Collect tool results to save AFTER assistant message (for correct chronological order)
424→          const pendingToolResults: Array<{
425→            toolCallId: string;
426→            toolName: string;
427→            output: unknown;
428→          }> = [];
429→          let inputTokens = 0;
430→          let outputTokens = 0;
431→
432→          // Stream the response with agentic loop control
433→          const result = await streamText({
434→            model,
435→            messages,
436→            tools,
437→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
438→            onChunk: async ({ chunk }) => {
439→              // Stream tool calls as they come in and capture their inputs
440→              if (chunk.type === 'tool-call') {
441→                const input = 'args' in chunk ? chunk.args : chunk.input;
442→
443→                // Log tool call for debugging
444→                console.log('[Agent] Tool call initiated:', {
445→                  toolName: chunk.toolName,
446→                  toolCallId: chunk.toolCallId,
447→                  input: JSON.stringify(input).slice(0, 500),
448→                });
449→
450→                // Store tool call with input for later persistence
451→                toolCallsMap.set(chunk.toolCallId, {
452→                  toolCallId: chunk.toolCallId,
453→                  toolName: chunk.toolName,
454→                  args: input,
455→                });
456→                sendEvent('tool_call', {
457→                  toolCallId: chunk.toolCallId,
458→                  toolName: chunk.toolName,
459→                  input,
460→                });
461→              }
462→            },
463→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
464→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
465→              // Capture tool calls from step finish (backup in case onChunk missed any)
466→              if (toolCalls && Array.isArray(toolCalls)) {
467→                for (const tc of toolCalls) {
468→                  if (!toolCallsMap.has(tc.toolCallId)) {
469→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
470→                    const args =
471→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
472→                    toolCallsMap.set(tc.toolCallId, {
473→                      toolCallId: tc.toolCallId,
474→                      toolName: tc.toolName,
475→                      args,
476→                    });
477→                  }
478→                }
479→              }
480→
481→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
482→              if (toolResults && toolResults.length > 0) {
483→                for (const tr of toolResults) {
484→                  // Check if this is an error result (AI SDK wraps errors in the output)
485→                  const isError =
486→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
487→
488→                  // Log tool results for debugging
489→                  if (isError) {
490→                    console.error('[Agent] Tool execution failed:', {
491→                      toolName: tr.toolName,
492→                      toolCallId: tr.toolCallId,
493→                      error: tr.output,
494→                    });
495→                  } else {
496→                    console.log('[Agent] Tool execution success:', {
497→                      toolName: tr.toolName,
498→                      toolCallId: tr.toolCallId,
499→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
500→                    });
501→                  }
502→
503→                  sendEvent('tool_result', {
504→                    toolCallId: tr.toolCallId,
505→                    output: tr.output,
506→                    isError,
507→                  });
508→
509→                  // Collect tool results to save after assistant message
510→                  pendingToolResults.push({
511→                    toolCallId: tr.toolCallId,
512→                    toolName: tr.toolName,
513→                    output: tr.output,
514→                  });
515→
516→                  // Track each tool call execution event
517→                  trackExecution({
518→                    eventType: 'tool_call',
519→                    source: 'agent_chat',
520→                    userId: authResult.userId ?? undefined,
521→                    apiKeyId: authResult.apiKeyId ?? undefined,
522→                    agentId: agent.id,
523→                    toolName: tr.toolName,
524→                    status: isError ? 'error' : 'success',
525→                  });
526→                }
527→              }
528→
529→              // Track token usage
530→              if (usage) {
531→                inputTokens += usage.inputTokens ?? 0;
532→                outputTokens += usage.outputTokens ?? 0;
533→              }
534→            },
535→          });
536→
537→          // Stream text chunks
538→          for await (const chunk of result.textStream) {
539→            fullContent += chunk;
540→            sendEvent('chunk', { type: 'text', text: chunk });
541→          }
542→
543→          // Get final response data
544→          const finalUsage = await result.usage;
545→
546→          // Convert tool calls map to array for storage
547→          const allToolCalls = Array.from(toolCallsMap.values());
548→
549→          // Update token counts from final usage
550→          if (finalUsage) {
551→            inputTokens = finalUsage.inputTokens ?? inputTokens;
552→            outputTokens = finalUsage.outputTokens ?? outputTokens;
553→          }
554→
555→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
556→          const assistantMessage = await prisma.message.create({
557→            data: {
558→              conversationId: conversation.id,
559→              role: 'ASSISTANT',
560→              content: fullContent,
561→              // Cast to Prisma-compatible JSON type
562→              toolCalls:
563→                allToolCalls.length > 0
564→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
565→                  : Prisma.JsonNull,
566→              inputTokens,
567→              outputTokens,
568→            },
569→          });
570→
571→          // Now save TOOL messages (after assistant, for correct chronological order)
572→          for (const tr of pendingToolResults) {
573→            await prisma.message.create({
574→              data: {
575→                conversationId: conversation.id,
576→                role: 'TOOL',
577→                content: JSON.stringify(tr.output),
578→                toolCallId: tr.toolCallId,
579→                toolName: tr.toolName,
580→                toolResult: tr.output as object,
581→              },
582→            });
583→          }
584→
585→          // Update conversation timestamp
586→          await prisma.conversation.update({
587→            where: { id: conversation.id },
588→            data: { updatedAt: new Date() },
589→          });
590→
591→          const executionTimeMs = Date.now() - startTime;
592→
593→          // Send token usage
594→          sendEvent('tokens', {
595→            inputTokens,
596→            outputTokens,
597→            totalTokens: inputTokens + outputTokens,
598→          });
599→
600→          // Send completion event
601→          sendEvent('complete', {
602→            messageId: assistantMessage.id,
603→            conversationId: conversation.id,
604→            executionTimeMs,
605→          });
606→
607→          // Track agent run execution event
608→          trackExecution({
609→            eventType: 'agent_run',
610→            source: 'agent_chat',
611→            userId: authResult.userId ?? undefined,
612→            apiKeyId: authResult.apiKeyId ?? undefined,
613→            agentId: agent.id,
614→            status: 'success',
615→            durationMs: executionTimeMs,
616→            tokensIn: inputTokens,
617→            tokensOut: outputTokens,
618→          });
619→
620→          // Track usage
621→          if (authResult.userId) {
622→            trackUsage({
623→              apiKeyId: authResult.apiKeyId ?? undefined,
624→              userId: authResult.userId,
625→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
626→              method: 'POST',
627→              statusCode: 200,
628→              latencyMs: executionTimeMs,
629→              resourceType: 'agent',
630→              resourceId: agentId,
631→              tokensIn: inputTokens,
632→              tokensOut: outputTokens,
633→              model: agent.modelId,
634→            });
635→          }
636→        } catch (error) {
637→          // Log detailed error for debugging
638→          console.error('[Agent] Conversation stream error:', {
639→            error: error instanceof Error ? error.message : String(error),
640→            stack: error instanceof Error ? error.stack : undefined,
641→            agentId: agent.id,
642→            conversationId: conversation.id,
643→          });
644→          sendEvent('error', {
645→            message: error instanceof Error ? error.message : 'Unknown error',
646→          });
647→
648→          // Track agent run error
649→          trackExecution({
650→            eventType: 'agent_run',
651→            source: 'agent_chat',
652→            userId: authResult.userId ?? undefined,
653→            apiKeyId: authResult.apiKeyId ?? undefined,
654→            agentId: agent.id,
655→            status: 'error',
656→            durationMs: Date.now() - startTime,
657→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
658→          });
659→
660→          // Track error
661→          if (authResult.userId) {
662→            trackUsage({
663→              apiKeyId: authResult.apiKeyId ?? undefined,
664→              userId: authResult.userId,
665→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
666→              method: 'POST',
667→              statusCode: 500,
668→              latencyMs: Date.now() - startTime,
669→              resourceType: 'agent',
670→              resourceId: agentId,
671→              errorCode: 'STREAM_ERROR',
672→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
673→            });
674→          }
675→        } finally {
676→          controller.close();
677→        }
678→      },
679→    });
680→
681→    return new NextResponse(stream, {
682→      headers: {
683→        'Content-Type': 'text/event-stream',
684→        'Cache-Control': 'no-cache',
685→        Connection: 'keep-alive',
686→      },
687→    });
688→  } catch (error) {
689→    console.error('Failed to process message:', error);
690→    return NextResponse.json(
691→      {
692→        success: false,
693→        error: error instanceof Error ? error.message : 'Failed to process message',
694→      },
695→      { status: 500 }
696→    );
697→  }
698→}
