700→/**
701→ * GET /api/agents/[id]/conversation/[conversationId]
702→ * Retrieve conversation history with pagination
703→ *
704→ * Query params:
705→ * - limit: Max messages to return (default: 50, max: 100)
706→ * - before: Fetch messages created before this ISO timestamp (for loading older messages)
707→ * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
708→ * - format: 'json' for full debug view (no pagination, includes agent info)
709→ *
710→ * Default behavior (no before/after): Returns the most recent messages
711→ * With before: Returns messages older than the timestamp (for scrolling up)
712→ * With after: Returns messages newer than the timestamp (for refreshing)
713→ */
714→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
715→  const { id: agentId, conversationId } = await context.params;
716→  const { searchParams } = new URL(request.url);
717→
718→  const format = searchParams.get('format');
719→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
720→  const before = searchParams.get('before');
721→  const after = searchParams.get('after');
722→
723→  try {
724→    // Fetch agent by ID with more details for JSON format
725→    const agent = await prisma.agent.findUnique({
726→      where: { id: agentId },
727→      select: {
728→        id: true,
729→        uid: true,
730→        name: true,
731→        provider: true,
732→        modelId: true,
733→        executorType: true,
734→        executorConfig: true,
735→      },
736→    });
737→
738→    if (!agent) {
739→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
740→    }
741→
742→    // Fetch conversation
743→    const conversation = await prisma.conversation.findUnique({
744→      where: {
745→        agentId_slug: {
746→          agentId: agent.id,
747→          slug: conversationId,
748→        },
749→      },
750→    });
751→
752→    if (!conversation) {
753→      return NextResponse.json(
754→        { success: false, error: 'Conversation not found' },
755→        { status: 404 }
756→      );
757→    }
758→
759→    // For JSON format, return all messages with full details
760→    if (format === 'json') {
761→      const allMessages = await prisma.message.findMany({
762→        where: { conversationId: conversation.id },
763→        orderBy: { createdAt: 'asc' },
764→      });
765→
766→      const response = {
767→        _meta: {
768→          exportedAt: new Date().toISOString(),
769→          format: 'tpmjs-conversation-log',
770→          version: '1.0',
771→        },
772→        agent: {
773→          id: agent.id,
774→          uid: agent.uid,
775→          name: agent.name,
776→          provider: agent.provider,
777→          modelId: agent.modelId,
778→          executorType: agent.executorType,
779→          executorConfig: agent.executorConfig,
780→        },
781→        conversation: {
782→          id: conversation.id,
783→          slug: conversation.slug,
784→          title: conversation.title,
785→          createdAt: conversation.createdAt,
786→          updatedAt: conversation.updatedAt,
787→          messageCount: allMessages.length,
788→        },
789→        messages: allMessages.map((m) => ({
790→          id: m.id,
791→          role: m.role,
792→          content: m.content,
793→          toolCalls: m.toolCalls,
794→          toolCallId: m.toolCallId,
795→          toolName: m.toolName,
796→          toolResult: m.toolResult,
797→          inputTokens: m.inputTokens,
798→          outputTokens: m.outputTokens,
799→          createdAt: m.createdAt,
800→        })),
801→        stats: {
802→          totalMessages: allMessages.length,
803→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
804→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
805→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
806→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
807→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
808→        },
809→      };
810→
811→      // Return pretty-printed JSON with proper content type
812→      return new NextResponse(JSON.stringify(response, null, 2), {
813→        headers: {
814→          'Content-Type': 'application/json',
815→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
816→        },
817→      });
818→    }
819→
820→    // Standard paginated response
821→    const whereClause: {
822→      conversationId: string;
823→      createdAt?: { lt?: Date; gt?: Date };
824→    } = { conversationId: conversation.id };
825→
826→    if (before) {
827→      whereClause.createdAt = { lt: new Date(before) };
828→    } else if (after) {
829→      whereClause.createdAt = { gt: new Date(after) };
830→    }
831→
832→    // Determine fetch order:
833→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
834→    // - "after": Fetch asc (oldest first) to get messages after the cursor
835→    const shouldFetchDesc = !after;
836→
837→    // Fetch messages
838→    const messages = await prisma.message.findMany({
839→      where: whereClause,
840→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
841→      take: limit + 1,
842→    });
843→
844→    const hasMore = messages.length > limit;
845→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
846→
847→    // Reverse if we fetched in desc order to maintain chronological order
848→    if (shouldFetchDesc) {
849→      paginatedMessages = paginatedMessages.reverse();
850→    }
851→
852→    const mappedMessages = paginatedMessages.map((m) => ({
853→      id: m.id,
854→      role: m.role,
855→      content: m.content,
856→      toolCalls: m.toolCalls,
857→      toolCallId: m.toolCallId,
858→      toolName: m.toolName,
859→      toolResult: m.toolResult,
860→      inputTokens: m.inputTokens,
861→      outputTokens: m.outputTokens,
862→      createdAt: m.createdAt,
863→    }));
864→
865→    return NextResponse.json({
866→      success: true,
867→      data: {
868→        id: conversation.id,
869→        slug: conversation.slug,
870→        title: conversation.title,
871→        createdAt: conversation.createdAt,
872→        updatedAt: conversation.updatedAt,
873→        messages: mappedMessages,
874→      },
875→      pagination: {
876→        limit,
877→        hasMore,
878→        ...(before && { before }),
879→        ...(after && { after }),
880→      },
881→    });
882→  } catch (error) {
883→    console.error('Failed to fetch conversation:', error);
884→    return NextResponse.json(
885→      { success: false, error: 'Failed to fetch conversation' },
886→      { status: 500 }
887→    );
888→  }
889→}
