891→/**
892→ * DELETE /api/agents/[id]/conversation/[conversationId]
893→ * Delete a conversation
894→ */
895→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
896→  const { id: agentId, conversationId } = await context.params;
897→
898→  try {
