            type: 'boolean',
            description: 'Create parent directories if they do not exist (default: true)',
          },
        },
        required: ['path', 'content'],
      },
      (p) => p
    ),
    listFiles: makeSandboxTool(
      'listFiles',
      'List files and directories in the sandbox workspace.',
