import { Prisma, prisma } from '@tpmjs/db';
import { UpdateAgentSchema } from '@tpmjs/types/agent';
import type { NextRequest } from 'next/server';

import { logActivity } from '~/lib/activity';
import { authenticateRequest } from '~/lib/api-keys/middleware';
import {
  apiConflict,
  apiForbidden,
  apiInternalError,
  apiNotFound,
  apiSuccess,
  apiUnauthorized,
  apiValidationError,
} from '~/lib/api-response';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

type RouteContext = {
  params: Promise<{ id: string }>;
};

/**
 * GET /api/agents/[id]
 * Get a single agent's details
 */
export async function GET(_request: NextRequest, context: RouteContext) {
  const requestId = crypto.randomUUID();

  try {
    const authResult = await authenticateRequest();
    const { id } = await context.params;

    const agent = await prisma.agent.findUnique({
      where: { id },
      include: {
        user: {
          select: {
            username: true,
          },
        },
        collections: {
          include: {
            collection: {
              select: {
                id: true,
                name: true,
                _count: { select: { tools: true } },
              },
            },
          },
          orderBy: { position: 'asc' },
          take: 50, // Limit to prevent excessive data fetch
        },
        tools: {
          include: {
            tool: {
              select: {
                id: true,
                name: true,
                description: true,
                parameters: true,
                package: {
                  select: {
                    npmPackageName: true,
                    category: true,
                  },
                },
              },
            },
          },
          orderBy: { position: 'asc' },
          take: 100, // Limit to prevent excessive data fetch
        },
        _count: {
          select: {
            tools: true,
            collections: true,
            conversations: true,
          },
        },
      },
    });

    if (!agent) {
      return apiNotFound('Agent', requestId);
    }

    // Check access - owner or public
    const isOwner = authResult.userId === agent.userId;
    if (!isOwner && !agent.isPublic) {
      return apiForbidden('Access denied', requestId);
    }

    return apiSuccess(
      {
        ...agent,
        isOwner,
        toolCount: agent._count.tools,
        collectionCount: agent._count.collections,
        conversationCount: agent._count.conversations,
        collections: agent.collections.map((ac) => ({
          id: ac.id,
          collectionId: ac.collectionId,
          position: ac.position,
          addedAt: ac.addedAt,
          collection: {
            ...ac.collection,
            toolCount: ac.collection._count.tools,
          },
        })),
        tools: agent.tools.map((at) => ({
          id: at.id,
          toolId: at.toolId,
          position: at.position,
          addedAt: at.addedAt,
          tool: at.tool,
        })),
        _count: undefined,
      },
      { requestId }
    );
  } catch (error) {
    console.error('Failed to get agent:', error);
    return apiInternalError('Failed to get agent', requestId);
  }
}

/**
 * PATCH /api/agents/[id]
 * Update an agent's configuration
 */
// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: large PATCH handler with many optional fields
export async function PATCH(request: NextRequest, context: RouteContext) {
  const requestId = crypto.randomUUID();

  try {
    const authResult = await authenticateRequest();
    if (!authResult.authenticated || !authResult.userId) {
      return apiUnauthorized('Authentication required', requestId);
    }

    const { id } = await context.params;
    const body = await request.json();
    const parsed = UpdateAgentSchema.safeParse(body);
    if (!parsed.success) {
      return apiValidationError(
        'Invalid request body',
        { errors: parsed.error.flatten().fieldErrors },
        requestId
      );
    }

    // Check ownership
    const existing = await prisma.agent.findUnique({
      where: { id },
      select: { userId: true },
    });
    if (!existing) {
      return apiNotFound('Agent', requestId);
    }
    if (existing.userId !== authResult.userId) {
      return apiForbidden('Access denied', requestId);
    }

    // Check UID uniqueness if being changed
    if (parsed.data.uid) {
      const existingByUid = await prisma.agent.findFirst({
        where: { uid: parsed.data.uid, id: { not: id } },
      });
      if (existingByUid) {
        return apiConflict('UID already in use', requestId);
      }
    }

    // Check name uniqueness if being changed
    if (parsed.data.name) {
      const existingByName = await prisma.agent.findFirst({
        where: { userId: authResult.userId, name: parsed.data.name, id: { not: id } },
      });
      if (existingByName) {
        return apiConflict('An agent with this name already exists', requestId);
      }
    }

    // Build update data, transforming JSON fields for Prisma (null -> Prisma.JsonNull)
    const { executorConfig, envVars, sandboxEnabled, ...restData } = parsed.data;
    const updateData: Prisma.AgentUpdateInput = {
      ...restData,
      ...(executorConfig !== undefined && {
        executorConfig: executorConfig === null ? Prisma.JsonNull : executorConfig,
      }),
      ...(envVars !== undefined && {
        envVars: envVars === null ? Prisma.JsonNull : envVars,
      }),
    };

    const agent = await prisma.agent.update({
      where: { id },
      data: updateData,
      include: {
        _count: {
          select: {
            tools: true,
            collections: true,
          },
        },
      },
    });

    // Log activity (fire-and-forget)
    const hasConfigChange =
      parsed.data.modelId !== undefined ||
      parsed.data.temperature !== undefined ||
      parsed.data.systemPrompt !== undefined ||
      parsed.data.provider !== undefined;
    logActivity({
      userId: authResult.userId,
      type: hasConfigChange ? 'AGENT_CONFIG_UPDATED' : 'AGENT_UPDATED',
      targetName: agent.name,
      targetType: 'agent',
      agentId: agent.id,
    });

    return apiSuccess(
      {
        ...agent,
        toolCount: agent._count.tools,
        collectionCount: agent._count.collections,
        _count: undefined,
      },
      { requestId }
    );
  } catch (error) {
    console.error('Failed to update agent:', error);
    return apiInternalError('Failed to update agent', requestId);
  }
}

