      if (customUrl) {
        onChange({
          type: 'custom_url',
          url: customUrl,
          apiKey: apiKey || undefined,
        });
      }
    } else if (type === 'sandbox') {
      onChange({
        type: 'sandbox',
        url: customUrl || undefined,
        apiKey: apiKey || undefined,
      });
    }
  };

  const handleUrlChange = (url: string) => {
    setCustomUrl(url);
    setVerificationResult(null);
    setUrlError(null);

    if (executorType === 'custom_url' && url) {
      onChange({
        type: 'custom_url',
        url,
        apiKey: apiKey || undefined,
      });
    } else if (executorType === 'sandbox') {
      onChange({
        type: 'sandbox',
        url: url || undefined,
        apiKey: apiKey || undefined,
      });
    }
  };

  const handleApiKeyChange = (key: string) => {
    setApiKey(key);

    if (executorType === 'custom_url' && customUrl) {
      onChange({
        type: 'custom_url',
        url: customUrl,
        apiKey: key || undefined,
      });
    } else if (executorType === 'sandbox') {
      onChange({
        type: 'sandbox',
        url: customUrl || undefined,
        apiKey: key || undefined,
      });
    }
  };

  const handleVerify = async () => {
    const urlToVerify = customUrl;
    if (!urlToVerify) {
      if (executorType === 'custom_url') {
        setUrlError('URL is required');
      } else {
        setUrlError('URL is required for verification');
      }
      return;
    }

    try {
      new URL(urlToVerify);
    } catch {
      setUrlError('Invalid URL format');
      return;
