import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Switch } from '@tpmjs/ui/Switch/Switch';
import Link from 'next/link';

interface SandboxToggleProps {
  enabled: boolean;
  onChange: (enabled: boolean) => void;
  disabled?: boolean;
}

export function SandboxToggle({
  enabled,
