 655→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Agent detail page has multiple interconnected features
 656→export default function AgentDetailPage(): React.ReactElement {
 657→  const params = useParams();
 658→  const router = useRouter();
 659→  const searchParams = useSearchParams();
 660→  const agentId = params.id as string;
 661→
 662→  // Get initial tab from URL or default to 'tools'
 663→  const tabFromUrl = searchParams.get('tab') as PageTabId | null;
 664→  const initialTab = tabFromUrl && VALID_TABS.includes(tabFromUrl) ? tabFromUrl : 'tools';
 665→
 666→  const [agent, setAgent] = useState<Agent | null>(null);
 667→  const [isLoading, setIsLoading] = useState(true);
 668→  const [isSaving, setIsSaving] = useState(false);
 669→  const [error, setError] = useState<string | null>(null);
 670→  const [executorConfig, setExecutorConfig] = useState<ExecutorConfig | null>(null);
 671→  const [sandboxEnabled, setSandboxEnabled] = useState(false);
 672→  const [activeTab, setActiveTab] = useState<PageTabId>(initialTab);
 673→
 674→  // Update URL when tab changes
 675→  const handleTabChange = (tabId: string) => {
 676→    const newTab = tabId as PageTabId;
 677→    setActiveTab(newTab);
 678→    const newParams = new URLSearchParams(searchParams.toString());
 679→    if (newTab === 'tools') {
 680→      newParams.delete('tab');
 681→    } else {
 682→      newParams.set('tab', newTab);
 683→    }
 684→    const queryString = newParams.toString();
 685→    router.replace(`/dashboard/agents/${agentId}${queryString ? `?${queryString}` : ''}`, {
 686→      scroll: false,
 687→    });
 688→  };
 689→
 690→  // Tools state
 691→  const [agentTools, setAgentTools] = useState<AgentTool[]>([]);
 692→  const [toolSearch, setToolSearch] = useState('');
 693→  const [toolSearchResults, setToolSearchResults] = useState<SearchTool[]>([]);
 694→  const [isSearchingTools, setIsSearchingTools] = useState(false);
 695→  const [showToolSearch, setShowToolSearch] = useState(false);
 696→  const toolSearchRef = useRef<HTMLDivElement>(null);
 697→
 698→  // Collections state
 699→  const [agentCollections, setAgentCollections] = useState<AgentCollection[]>([]);
 700→  const [collectionSearch, setCollectionSearch] = useState('');
 701→  const [collectionSearchResults, setCollectionSearchResults] = useState<SearchCollection[]>([]);
 702→  const [isSearchingCollections, setIsSearchingCollections] = useState(false);
 703→  const [showCollectionSearch, setShowCollectionSearch] = useState(false);
 704→  const collectionSearchRef = useRef<HTMLDivElement>(null);
 705→
 706→  const [formData, setFormData] = useState({
 707→    name: '',
 708→    uid: '',
 709→    description: '',
 710→    provider: 'OPENAI' as AIProvider,
 711→    modelId: '',
 712→    systemPrompt: '',
 713→    temperature: 0.7,
 714→    maxToolCallsPerTurn: 20,
 715→    maxMessagesInContext: 10,
 716→    isPublic: true,
 717→  });
 718→
 719→  // Environment variables state (stored as object for the EnvVarsEditor component)
 720→  const [envVars, setEnvVars] = useState<Record<string, string> | null>(null);
 721→
 722→  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Multiple state initialization from fetched data
 723→  const fetchAgent = useCallback(async () => {
 724→    try {
 725→      const response = await fetch(`/api/agents/${agentId}`);
 726→      const data = await response.json();
 727→
 728→      if (data.success) {
 729→        setAgent(data.data);
 730→        setFormData({
 731→          name: data.data.name,
 732→          uid: data.data.uid,
 733→          description: data.data.description || '',
 734→          provider: data.data.provider,
 735→          modelId: data.data.modelId,
 736→          systemPrompt: data.data.systemPrompt || '',
 737→          temperature: data.data.temperature,
 738→          maxToolCallsPerTurn: data.data.maxToolCallsPerTurn,
 739→          maxMessagesInContext: data.data.maxMessagesInContext,
 740→          isPublic: data.data.isPublic,
 741→        });
 742→        // Initialize sandbox toggle from agent data
 743→        setSandboxEnabled(data.data.sandboxEnabled ?? false);
 744→        // Initialize executor config state from agent data
 745→        if (data.data.executorType === 'custom_url' && data.data.executorConfig) {
 746→          setExecutorConfig({
 747→            type: 'custom_url',
 748→            url: data.data.executorConfig.url,
 749→            apiKey: data.data.executorConfig.apiKey,
 750→          });
 751→        } else {
 752→          setExecutorConfig(data.data.executorType ? { type: 'default' } : null);
 753→        }
 754→        // Initialize env vars from agent data
 755→        if (data.data.envVars && typeof data.data.envVars === 'object') {
 756→          setEnvVars(data.data.envVars as Record<string, string>);
 757→        } else {
 758→          setEnvVars(null);
 759→        }
 760→      } else {
 761→        if (response.status === 401) {
 762→          router.push('/sign-in');
 763→          return;
 764→        }
 765→        setError(data.error || 'Failed to fetch agent');
 766→      }
 767→    } catch (err) {
 768→      console.error('Failed to fetch agent:', err);
 769→      setError('Failed to fetch agent');
 770→    } finally {
 771→      setIsLoading(false);
 772→    }
 773→  }, [agentId, router]);
 774→
 775→  // Fetch tools attached to agent
 776→  const fetchAgentTools = useCallback(async () => {
 777→    try {
 778→      const response = await fetch(`/api/agents/${agentId}/tools`);
 779→      const data = await response.json();
 780→      if (data.success) {
 781→        setAgentTools(data.data || []);
 782→      }
 783→    } catch (err) {
 784→      console.error('Failed to fetch agent tools:', err);
 785→    }
 786→  }, [agentId]);
 787→
 788→  // Fetch collections attached to agent
 789→  const fetchAgentCollections = useCallback(async () => {
 790→    try {
 791→      const response = await fetch(`/api/agents/${agentId}/collections`);
 792→      const data = await response.json();
 793→      if (data.success) {
 794→        setAgentCollections(data.data || []);
 795→      }
 796→    } catch (err) {
 797→      console.error('Failed to fetch agent collections:', err);
 798→    }
 799→  }, [agentId]);
 800→
 801→  useEffect(() => {
 802→    fetchAgent();
 803→  }, [fetchAgent]);
 804→
 805→  useEffect(() => {
 806→    if (agent) {
 807→      fetchAgentTools();
 808→      fetchAgentCollections();
 809→    }
 810→  }, [agent, fetchAgentTools, fetchAgentCollections]);
 811→
 812→  // Click outside handler for search dropdowns
 813→  useEffect(() => {
 814→    function handleClickOutside(event: MouseEvent) {
 815→      if (toolSearchRef.current && !toolSearchRef.current.contains(event.target as Node)) {
 816→        setShowToolSearch(false);
 817→      }
 818→      if (
 819→        collectionSearchRef.current &&
 820→        !collectionSearchRef.current.contains(event.target as Node)
 821→      ) {
 822→        setShowCollectionSearch(false);
 823→      }
 824→    }
 825→    document.addEventListener('mousedown', handleClickOutside);
 826→    return () => document.removeEventListener('mousedown', handleClickOutside);
 827→  }, []);
 828→
 829→  // Search tools
 830→  const searchTools = useCallback(
 831→    async (query: string) => {
 832→      if (!query.trim()) {
 833→        setToolSearchResults([]);
 834→        return;
 835→      }
 836→      setIsSearchingTools(true);
 837→      try {
 838→        const response = await fetch(`/api/tools/search?q=${encodeURIComponent(query)}&limit=10`);
 839→        const data = await response.json();
 840→        if (data.success && data.results?.tools) {
 841→          // Filter out tools already attached and map to expected shape
 842→          const attachedToolIds = new Set(agentTools.map((t) => t.toolId));
 843→          const filtered = data.results.tools
 844→            .filter((t: { id: string }) => !attachedToolIds.has(t.id))
 845→            .map(
 846→              (t: {
 847→                id: string;
 848→                name: string;
 849→                description: string | null;
 850→                package: { npmPackageName: string };
 851→              }) => ({
 852→                id: t.id,
 853→                name: t.name,
 854→                description: t.description,
 855→                npmPackageName: t.package.npmPackageName,
 856→              })
 857→            );
 858→          setToolSearchResults(filtered);
 859→        }
 860→      } catch (err) {
 861→        console.error('Failed to search tools:', err);
 862→      } finally {
 863→        setIsSearchingTools(false);
 864→      }
 865→    },
 866→    [agentTools]
 867→  );
 868→
 869→  // Search collections
 870→  const searchCollections = useCallback(
 871→    async (query: string) => {
 872→      if (!query.trim()) {
 873→        setCollectionSearchResults([]);
 874→        return;
 875→      }
 876→      setIsSearchingCollections(true);
 877→      try {
 878→        const response = await fetch(
 879→          `/api/collections?search=${encodeURIComponent(query)}&limit=10`
 880→        );
 881→        const data = await response.json();
 882→        if (data.success) {
 883→          // Filter out collections already attached
 884→          const attachedCollectionIds = new Set(agentCollections.map((c) => c.collectionId));
 885→          const filtered = (data.data || []).filter(
 886→            (c: SearchCollection) => !attachedCollectionIds.has(c.id)
 887→          );
 888→          setCollectionSearchResults(filtered);
 889→        }
 890→      } catch (err) {
 891→        console.error('Failed to search collections:', err);
 892→      } finally {
 893→        setIsSearchingCollections(false);
 894→      }
 895→    },
 896→    [agentCollections]
 897→  );
 898→
 899→  // Debounced search effects
 900→  useEffect(() => {
 901→    const timer = setTimeout(() => {
 902→      if (toolSearch) searchTools(toolSearch);
 903→    }, 300);
 904→    return () => clearTimeout(timer);
 905→  }, [toolSearch, searchTools]);
 906→
 907→  useEffect(() => {
 908→    const timer = setTimeout(() => {
