 927→        setToolSearchResults([]);
 928→        setShowToolSearch(false);
 929→      } else {
 930→        alert(data.error || 'Failed to add tool');
 931→      }
 932→    } catch (err) {
 933→      console.error('Failed to add tool:', err);
 934→      alert('Failed to add tool');
 935→    }
 936→  };
 937→
 938→  // Remove tool from agent
 939→  const removeTool = async (toolId: string) => {
 940→    try {
 941→      const response = await fetch(`/api/agents/${agentId}/tools/${toolId}`, {
